/**
 * Core type definitions for .riv file format
 * Based on rive-runtime core defs
 */
// Field types used in the Table of Contents
export const FieldType = {
    VarUint: 0, // Variable-length unsigned integer
    String: 1, // Length-prefixed string
    Float: 2, // 32-bit float (actually stored as double in some cases)
    Color: 3, // 32-bit color (ARGB)
};
// Object type keys from core defs
export const ObjectType = {
    // Core types
    Backboard: 23,
    Artboard: 1,
    Node: 2,
    // Shapes
    Shape: 3,
    Ellipse: 4,
    Rectangle: 7,
    Triangle: 8,
    Polygon: 59,
    Star: 60,
    Path: 14,
    // Paths
    ParametricPath: 15,
    PointsPath: 16,
    StraightVertex: 5,
    CubicVertex: 6,
    CubicMirroredVertex: 35,
    CubicAsymmetricVertex: 34,
    CubicDetachedVertex: 36,
    // Paints
    Fill: 20,
    Stroke: 24,
    SolidColor: 18,
    LinearGradient: 22,
    RadialGradient: 17,
    GradientStop: 19,
    // Containers
    ContainerComponent: 11,
    // Transform
    TransformComponent: 38,
    WorldTransformComponent: 39,
    // Layout
    LayoutComponent: 409,
    // Drawable
    Drawable: 13,
    // Animation
    LinearAnimation: 31,
    KeyedObject: 25,
    KeyedProperty: 26,
    KeyFrameDouble: 30,
};
// Property keys from core defs
export const PropertyKey = {
    // Component (base)
    name: 4,
    parentId: 5,
    // Layout/Artboard
    width: 7,
    height: 8,
    // Artboard-specific
    originX: 11,
    originY: 12,
    clip: 196,
    defaultStateMachineId: 236,
    // Node position
    x: 13,
    y: 14,
    // Transform
    rotation: 15,
    scaleX: 16,
    scaleY: 17,
    // ParametricPath (ellipse, rectangle, etc.)
    pathWidth: 20,
    pathHeight: 21,
    pathOriginX: 123,
    pathOriginY: 124,
    // Rectangle-specific
    cornerRadiusTL: 31,
    cornerRadiusTR: 161,
    cornerRadiusBL: 162,
    cornerRadiusBR: 163,
    // Drawable
    blendModeValue: 23,
    drawableFlags: 129,
    // ShapePaint
    isVisible: 41,
    paintBlendModeValue: 747,
    // Fill
    fillRule: 40,
    // SolidColor
    colorValue: 37,
    // Stroke
    thickness: 47,
    cap: 48,
    join: 49,
    // Gradient
    startX: 42,
    startY: 33,
    endX: 34,
    endY: 35,
    opacity: 46,
    // GradientStop
    stopColor: 38,
    stopPosition: 39,
    // Vertex
    vertexX: 24,
    vertexY: 25,
    // Cubic vertex control points
    inX: 26,
    inY: 27,
    outX: 28,
    outY: 29,
    // Path closed
    isClosed: 32,
    // Animation (LinearAnimation)
    fps: 56,
    duration: 57,
    speed: 58,
    loopValue: 59,
    workStart: 60,
    workEnd: 61,
    enableWorkArea: 62,
    // KeyedObject
    objectId: 51,
    // KeyedProperty
    propertyKeyId: 53,
    // KeyFrame
    frame: 67,
    interpolationType: 68,
    interpolatorId: 69,
    keyFrameValue: 70,
};
// Map property keys to their field types
export const PropertyFieldType = {
    // Strings
    [PropertyKey.name]: FieldType.String,
    // Unsigned integers (varuint)
    [PropertyKey.parentId]: FieldType.VarUint,
    [PropertyKey.blendModeValue]: FieldType.VarUint,
    [PropertyKey.drawableFlags]: FieldType.VarUint,
    [PropertyKey.fillRule]: FieldType.VarUint,
    [PropertyKey.cap]: FieldType.VarUint,
    [PropertyKey.join]: FieldType.VarUint,
    [PropertyKey.defaultStateMachineId]: FieldType.VarUint,
    [PropertyKey.paintBlendModeValue]: FieldType.VarUint,
    // Colors
    [PropertyKey.colorValue]: FieldType.Color,
    [PropertyKey.stopColor]: FieldType.Color,
    // Floats/Doubles (everything else)
    [PropertyKey.width]: FieldType.Float,
    [PropertyKey.height]: FieldType.Float,
    [PropertyKey.originX]: FieldType.Float,
    [PropertyKey.originY]: FieldType.Float,
    [PropertyKey.x]: FieldType.Float,
    [PropertyKey.y]: FieldType.Float,
    [PropertyKey.rotation]: FieldType.Float,
    [PropertyKey.scaleX]: FieldType.Float,
    [PropertyKey.scaleY]: FieldType.Float,
    [PropertyKey.pathWidth]: FieldType.Float,
    [PropertyKey.pathHeight]: FieldType.Float,
    [PropertyKey.pathOriginX]: FieldType.Float,
    [PropertyKey.pathOriginY]: FieldType.Float,
    [31]: FieldType.Float, // cornerRadiusTL
    [161]: FieldType.Float, // cornerRadiusTR
    [162]: FieldType.Float, // cornerRadiusBL
    [163]: FieldType.Float, // cornerRadiusBR
    [PropertyKey.thickness]: FieldType.Float,
    [42]: FieldType.Float, // startX
    [33]: FieldType.Float, // startY
    [34]: FieldType.Float, // endX
    [35]: FieldType.Float, // endY
    [PropertyKey.opacity]: FieldType.Float,
    [PropertyKey.stopPosition]: FieldType.Float,
    [PropertyKey.vertexX]: FieldType.Float,
    [PropertyKey.vertexY]: FieldType.Float,
    [PropertyKey.inX]: FieldType.Float,
    [PropertyKey.inY]: FieldType.Float,
    [PropertyKey.outX]: FieldType.Float,
    [PropertyKey.outY]: FieldType.Float,
};
// Booleans are stored as varuint (0 or 1)
[PropertyKey.clip, PropertyKey.isVisible, PropertyKey.isClosed, PropertyKey.enableWorkArea].forEach(key => {
    PropertyFieldType[key] = FieldType.VarUint;
});
// Animation property field types
PropertyFieldType[PropertyKey.fps] = FieldType.VarUint;
PropertyFieldType[PropertyKey.duration] = FieldType.VarUint;
PropertyFieldType[PropertyKey.loopValue] = FieldType.VarUint;
PropertyFieldType[PropertyKey.workStart] = FieldType.VarUint;
PropertyFieldType[PropertyKey.workEnd] = FieldType.VarUint;
PropertyFieldType[PropertyKey.speed] = FieldType.Float;
PropertyFieldType[PropertyKey.objectId] = FieldType.VarUint;
PropertyFieldType[PropertyKey.propertyKeyId] = FieldType.VarUint;
PropertyFieldType[PropertyKey.frame] = FieldType.VarUint;
PropertyFieldType[PropertyKey.interpolationType] = FieldType.VarUint;
PropertyFieldType[PropertyKey.interpolatorId] = FieldType.VarUint;
PropertyFieldType[PropertyKey.keyFrameValue] = FieldType.Float;
// File format constants
export const RIVE_FINGERPRINT = 'RIVE';
export const MAJOR_VERSION = 7;
export const MINOR_VERSION = 0;
